import copy
BASE = {"run": "A-0", "code": "a41c9e2", "data": "spirals-600 v1", "split_seed": 0, "seed": 0,
        "config": {"opt": "adam", "lr": 0.01, "hidden": 16, "batch": 32, "steps": 300},
        "events": [{"step": s, "kind": "loss", "train": 0.5, "val": 0.5} for s in range(6, 301, 6)]
                  + [{"step": 300, "kind": "test", "loss": 0.05}]}


def variant(drop=(), none=(), add=(), keep_losses=None):
    log = copy.deepcopy(BASE)
    for k in drop:
        del log[k]
    for k in none:
        log[k] = None
    if keep_losses is not None:
        losses = [e for e in log["events"] if e["kind"] == "loss"]
        log["events"] = losses[len(losses) - keep_losses:] + [e for e in log["events"] if e["kind"] != "loss"]
    log["events"] = sorted(log["events"] + list(add), key=lambda e: e["step"])
    return log

